class AutomaticGuitarSimulator:
    def __init__(self, text) -> None:
        self.play_text = text

    def interpret(self, display=False):
        if not self.play_text or not self.play_text.strip():
            return []
        play_list = []
        parts = self.play_text.strip().split()
        for part in parts:
            # Split into leading letters (Chord) and trailing digits (Tune)
            i = 0
            while i < len(part) and not part[i].isdigit():
                i += 1
            chord = part[:i]
            tune = part[i:]
            entry = {'Chord': chord, 'Tune': tune}
            play_list.append(entry)
            if display:
                print(self.display(chord, tune))
        return play_list

    def display(self, key, value):
        result = f"Normal Guitar Playing -- Chord: {key}, Play Tune: {value}"
        print(result)
        return result

