class BoyerMooreSearch:
    def __init__(self, text, pattern):
        self.text, self.pattern = text, pattern
        self.textLen, self.patLen = len(text), len(pattern)

    def match_in_pattern(self, char):
        # Find the rightmost occurrence of char in the pattern
        for i in range(self.patLen - 1, -1, -1):
            if self.pattern[i] == char:
                return i
        return -1

    def mismatch_in_text(self, currentPos):
        # Compare pattern with text starting at currentPos
        # Returns the index in pattern where mismatch occurs, or -1 if full match
        for i in range(self.patLen - 1, -1, -1):
            if self.pattern[i] != self.text[currentPos + i]:
                return i
        return -1

    def bad_character_heuristic(self):
        # If pattern is empty, return all positions from 0 to textLen inclusive
        if self.patLen == 0:
            return list(range(self.textLen + 1))

        positions = []
        currentPos = 0
        while currentPos <= self.textLen - self.patLen:
            mismatch_index = self.mismatch_in_text(currentPos)
            if mismatch_index == -1:
                # Full match found
                positions.append(currentPos)
                currentPos += 1
            else:
                # Bad character heuristic
                bad_char = self.text[currentPos + mismatch_index]
                char_pos = self.match_in_pattern(bad_char)
                if char_pos == -1:
                    currentPos += mismatch_index + 1
                else:
                    shift = mismatch_index - char_pos
                    if shift > 0:
                        currentPos += shift
                    else:
                        currentPos += 1
        return positions

