class DataStatistics4:
    """
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    """

    @staticmethod
    def correlation_coefficient(data1, data2):
        n = len(data1)
        mean1 = sum(data1) / n
        mean2 = sum(data2) / n
        numerator = sum((data1[i] - mean1) * (data2[i] - mean2) for i in range(n))
        denom1 = math.sqrt(sum((x - mean1) ** 2 for x in data1))
        denom2 = math.sqrt(sum((x - mean2) ** 2 for x in data2))
        if denom1 == 0 or denom2 == 0:
            return 0
        return numerator / (denom1 * denom2)

    @staticmethod
    def skewness(data):
        n = len(data)
        mean = sum(data) / n
        variance = sum((x - mean) ** 2 for x in data) / n
        std = math.sqrt(variance)
        if std == 0:
            return 0
        skew = sum((x - mean) ** 3 for x in data) / n / (std ** 3)
        return skew

    @staticmethod
    def kurtosis(data):
        n = len(data)
        mean = sum(data) / n
        variance = sum((x - mean) ** 2 for x in data) / n
        if variance == 0:
            return float('nan')
        kurt = sum((x - mean) ** 4 for x in data) / n / (variance ** 2) - 3
        return kurt

    @staticmethod
    def pdf(data, mu, sigma):
        result = []
        for x in data:
            val = (1 / (sigma * math.sqrt(2 * math.pi))) * math.exp(-0.5 * ((x - mu) / sigma) ** 2)
            result.append(val)
        return result

