                base = ord('A') if char.isupper() else ord('a')
                result.append(chr((ord(char) - base - shift) % 26 + base))
            else:
                result.append(char)
        return ''.join(result)

    def vigenere_decipher(self, ciphertext):
        result = []
        key = self.key
        key_index = 0
        for char in ciphertext:
            if char.isalpha():
                base = ord('A') if char.isupper() else ord('a')
                key_char = key[key_index % len(key)]
                key_base = ord('A') if key_char.isupper() else ord('a')
                shift = ord(key_char) - key_base
                result.append(chr((ord(char) - base - shift) % 26 + base))
                key_index += 1
            else:
                result.append(char)
        return ''.join(result)

    def rail_fence_decipher(self, encrypted_text, rails):
        n = len(encrypted_text)
        if rails == 1:
            return encrypted_text

        # Determine the pattern of rail indices
        pattern = []
        rail = 0
        direction = 1
        for i in range(n):
            pattern.append(rail)
            if rail == rails - 1:
                direction = -1
            elif rail == 0:
                direction = 1
            rail += direction

        # Count characters per rail
        rail_lengths = [0] * rails
        for r in pattern:
            rail_lengths[r] += 1

        # Split encrypted_text into rails
