        idx = 0
        for r in range(rails):
            rail_strings.append(list(encrypted_text[idx:idx + rail_lengths[r]]))
            idx += rail_lengths[r]

        # Read off in zigzag order
        rail_indices = [0] * rails
        result = []
        for r in pattern:
