    def __init__(self, initial_state):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state):
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return (i, j)
        return None

    def move(self, state, direction):
        import copy
        blank = self.find_blank(state)
        if blank is None:
            return state
        i, j = blank
        new_state = copy.deepcopy(state)
        if direction == 'up':
            if i > 0:
                new_state[i][j], new_state[i-1][j] = new_state[i-1][j], new_state[i][j]
        elif direction == 'down':
            if i < 2:
                new_state[i][j], new_state[i+1][j] = new_state[i+1][j], new_state[i][j]
        elif direction == 'left':
            if j > 0:
                new_state[i][j], new_state[i][j-1] = new_state[i][j-1], new_state[i][j]
        elif direction == 'right':
            if j < 2:
                new_state[i][j], new_state[i][j+1] = new_state[i][j+1], new_state[i][j]
        return new_state

    def get_possible_moves(self, state):
        blank = self.find_blank(state)
        if blank is None:
            return []
        i, j = blank
        moves = []
        if i > 0:
            moves.append('up')
        if i < 2:
            moves.append('down')
        if j > 0:
            moves.append('left')
        if j < 2:
            moves.append('right')
        return moves

    def solve(self):
        import copy
        initial = self.initial_state
        goal = self.goal_state

        # Check if initial state is valid (has exactly one blank)
        blank = self.find_blank(initial)
        if blank is None:
            return None

        # Count zeros to check validity
        zero_count = sum(row.count(0) for row in initial)
        if zero_count != 1:
            return None

        if initial == goal:
            return []

        # BFS
        # Each element in queue: (state, path)
        queue = [(initial, [])]
        visited = set()
        visited.add(tuple(tuple(row) for row in initial))

        while queue:
            current_state, path = queue.pop(0)

            possible_moves = self.get_possible_moves(current_state)
            for direction in possible_moves:
                new_state = self.move(current_state, direction)
                state_tuple = tuple(tuple(row) for row in new_state)

                if state_tuple not in visited:
                    new_path = path + [direction]
                    if new_state == goal:
                        return new_path
                    visited.add(state_tuple)
                    queue.append((new_state, new_path))

        return None

