    def __init__(self):
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN", "EIGHTEEN", "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        if x is None:
            return ""
        return self.format_string(str(x))

    def format_string(self, x):
        if x is None or x == '':
            return ""
        if '.' in str(x):
            parts = str(x).split('.')
            int_part = parts[0]
            dec_part = parts[1]
            int_words = self._convert_integer(int_part)
            dec_words = self.trans_two(dec_part.ljust(2, '0')[:2])
            if int_words == '' and dec_words == '':
                return "ZERO ONLY"
            if int_words == '':
                int_words = 'ZERO'
            result = int_words + " AND CENTS " + dec_words + " ONLY"
            return result
        else:
            int_part = str(x)
            int_words = self._convert_integer(int_part)
            if int_words == '':
                return "ZERO ONLY"
            return int_words + " ONLY"

    def _convert_integer(self, s):
        s = s.strip()
        if not s or int(s) == 0:
            return ''
        # Pad to multiple of 3
        while len(s) % 3 != 0:
            s = '0' + s
        # Split into groups of 3
        groups = []
        for i in range(0, len(s), 3):
            groups.append(s[i:i+3])
        # groups[0] is the most significant
        result_parts = []
        num_groups = len(groups)
        for i, grp in enumerate(groups):
            mag = num_groups - 1 - i
            words = self.trans_three(grp)
            if words:
                if mag > 0:
                    suffix = self.parse_more(mag)
                    result_parts.append(words + " " + suffix)
                else:
                    result_parts.append(words)
        return ' '.join(result_parts)

    def trans_two(self, s):
        if not s or len(s) < 2:
            if not s:
                return ''
            s = s.zfill(2)
        s = s[:2]
        ten = int(s[0])
        one = int(s[1])
        if ten == 0:
            return self.NUMBER[one]
        elif ten == 1:
            return self.NUMBER_TEEN[one]
        else:
            if one == 0:
                return self.NUMBER_TEN[ten - 1]
            else:
                return self.NUMBER_TEN[ten - 1] + ' ' + self.NUMBER[one]

    def trans_three(self, s):
        if not s or len(s) < 3:
            s = s.zfill(3)
        s = s[:3]
        hundred = int(s[0])
        rest = s[1:]
        two_words = self.trans_two(rest)
        if hundred == 0:
            return two_words
        else:
            hundred_words = self.NUMBER[hundred] + ' HUNDRED'
            if two_words:
                return hundred_words + ' AND ' + two_words
            else:
                return hundred_words

    def parse_more(self, i):
        return self.NUMBER_MORE[i]

