class PushBoxGame:
    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False
        self.init_game()

    def init_game(self):
        for r, row in enumerate(self.map):
            for c, cell in enumerate(row):
                if cell == 'O':
                    self.player_row = r
                    self.player_col = c
                elif cell == 'G':
                    self.targets.append((r, c))
                elif cell == 'X':
                    self.boxes.append((r, c))
        self.target_count = len(self.targets)

    def check_win(self):
        for box in self.boxes:
            if box not in self.targets:
                self.is_game_over = False
                return False
        self.is_game_over = True
        return True

    def move(self, direction):
        if direction == 'w':
            dr, dc = -1, 0
        elif direction == 's':
            dr, dc = 1, 0
        elif direction == 'a':
            dr, dc = 0, -1
        elif direction == 'd':
            dr, dc = 0, 1
        else:
            return self.is_game_over

        new_row = self.player_row + dr
        new_col = self.player_col + dc

        # Check bounds and wall
        if new_row < 0 or new_row >= len(self.map) or new_col < 0 or new_col >= len(self.map[new_row]):
            return self.is_game_over
        if self.map[new_row][new_col] == '#':
            return self.is_game_over

        # Check if there's a box
        if (new_row, new_col) in self.boxes:
            box_new_row = new_row + dr
            box_new_col = new_col + dc
            # Check if box can move
            if box_new_row < 0 or box_new_row >= len(self.map) or box_new_col < 0 or box_new_col >= len(self.map[box_new_row]):
                return self.is_game_over
            if self.map[box_new_row][box_new_col] == '#':
                return self.is_game_over
            if (box_new_row, box_new_col) in self.boxes:
                return self.is_game_over
            # Move box
            idx = self.boxes.index((new_row, new_col))
            self.boxes[idx] = (box_new_row, box_new_col)

        # Move player
        self.player_row = new_row
        self.player_col = new_col

        return self.check_win()

