class StockPortfolioTracker:
    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        for s in self.portfolio:
            if s['name'] == stock['name']:
                s['quantity'] += stock['quantity']
                return
        self.portfolio.append({'name': stock['name'], 'price': stock['price'], 'quantity': stock['quantity']})

    def remove_stock(self, stock):
        for s in self.portfolio:
            if s['name'] == stock['name']:
                if s['quantity'] < stock['quantity']:
                    return False
                s['quantity'] -= stock['quantity']
                if s['quantity'] == 0:
                    self.portfolio.remove(s)
                return True
        return False

    def buy_stock(self, stock):
        cost = stock['price'] * stock['quantity']
        if cost > self.cash_balance:
            return False
        self.cash_balance -= cost
        self.add_stock(stock)
        return True

    def sell_stock(self, stock):
        for s in self.portfolio:
            if s['name'] == stock['name']:
                if s['quantity'] < stock['quantity']:
                    return False
                s['quantity'] -= stock['quantity']
                self.cash_balance += stock['price'] * stock['quantity']
                if s['quantity'] == 0:
                    self.portfolio.remove(s)
                return True
        return False

    def calculate_portfolio_value(self):
        total = self.cash_balance
        for s in self.portfolio:
            total += s['price'] * s['quantity']
        return total

    def get_portfolio_summary(self):
        total_value = self.calculate_portfolio_value()
        summary = [{'name': s['name'], 'value': s['price'] * s['quantity']} for s in self.portfolio]
        return (total_value, summary)

    def get_stock_value(self, stock):
        return stock['price'] * stock['quantity']

