    """
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    """

    def __init__(self, url):
        self.url = url

    def get_scheme(self):
        if '://' not in self.url:
            return None
        return self.url.split('://')[0]

    def get_host(self):
        if '://' not in self.url:
            return None
        rest = self.url.split('://', 1)[1]
        # host is everything up to the first '/' or end of string
        if '/' in rest:
            host = rest.split('/', 1)[0]
        else:
            host = rest
        if not host:
            return None
        return host

    def get_path(self):
        if '://' not in self.url:
            return None
        rest = self.url.split('://', 1)[1]
        if '/' not in rest:
            return None
        path = '/' + rest.split('/', 1)[1]
        if path == '/':
            return None
        return path

    def get_query_params(self):
        # Find query string - between '?' and '#' (if present)
        if '?' not in self.url:
            return None
        query_part = self.url.split('?', 1)[1]
        # Remove fragment
        if '#' in query_part:
            query_part = query_part.split('#', 1)[0]
        # Parse query params
        params = {}
        if not query_part:
            return params
        pairs = query_part.split('&')
        for pair in pairs:
            if not pair:
