from gensim import matutils
from numpy import dot, array
import math

class VectorUtil:
    """
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    """

    @staticmethod
    def similarity(vector_1, vector_2):
        return float(matutils.cossim(matutils.unitvec(vector_1), matutils.unitvec(vector_2)))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        norm = np.linalg.norm(vector_1)
        if norm == 0:
            return np.zeros(len(vectors_all))
        v1 = vector_1 / norm
        results = []
        for v in vectors_all:
            n = np.linalg.norm(v)
            if n == 0:
                results.append(0.0)
            else:
                results.append(float(np.dot(v1, v / n)))
        return np.array(results)

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if not vector_list_1 or not vector_list_2:
            raise ValueError("Empty vector list")
        avg1 = np.mean(vector_list_1, axis=0)
        avg2 = np.mean(vector_list_2, axis=0)
        return float(matutils.cossim(matutils.unitvec(avg1), matutils.unitvec(avg2)))

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        result = {}
        for key, count in number_dict.items():
            result[key] = math.log((total_num + 1) / (count + 1))
        return result

